Generated Query:
PREFIX in: <http://data.world/schema/insurance/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?policyNumber ?premiumValue
       (COUNT(DISTINCT ?claim) AS ?numberOfClaims)
       (SUM(?lossComponent) AS ?totalLoss)
       ((SUM(?lossComponent) / ?premiumValue) AS ?lossRatio)
WHERE {
  SERVICE <mapped> {
    ?pcd a in:PolicyCoverageDetail ;
         in:hasPolicy ?policy ;
         in:hasPremiumAmount ?premium .

    ?policy in:policyNumber ?policyNumber .

    ?premium in:premiumAmount ?premiumAmtRaw .

    BIND(xsd:decimal(?premiumAmtRaw) AS ?premiumValue)

    ?claim a in:Claim ;
           in:against ?pcd .

    {
      ?claim in:hasLossPayment ?lp .
      ?lp in:lossPaymentAmount ?amtRaw .
      BIND(xsd:decimal(?amtRaw) AS ?lossComponent)
    }
    UNION
    {
      ?claim in:hasLossReserve ?lr .
      ?lr in:lossReserveAmount ?amtRaw .
      BIND(xsd:decimal(?amtRaw) AS ?lossComponent)
    }
    UNION
    {
      ?claim in:hasExpensePayment ?ep .
      ?ep in:expensePaymentAmount ?amtRaw .
      BIND(xsd:decimal(?amtRaw) AS ?lossComponent)
    }
    UNION
    {
      ?claim in:hasExpenseReserve ?er .
      ?er in:expenseReserveAmount ?amtRaw .
      BIND(xsd:decimal(?amtRaw) AS ?lossComponent)
    }
  }
}
GROUP BY ?policyNumber ?premiumValue
ORDER BY ?policyNumber

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?policyHolder ?policyHolderId (SUM(?amount) AS ?totalPremiumPaid)
WHERE {
  SERVICE <mapped> {
    ?policy in:hasPolicyHolder ?policyHolder .
    OPTIONAL { ?policyHolder in:policyHolderId ?policyHolderId . }

    ?coverageDetail in:hasPolicy ?policy ;
                    in:hasPremiumAmount ?premium .

    ?premium in:premiumAmount ?amount .
  }
}
GROUP BY ?policyHolder ?policyHolderId

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?agentId (COUNT(DISTINCT ?policy) AS ?policyCount)
WHERE {
  SERVICE <mapped> {
    ?policy a in:Policy ;
            in:soldByAgent ?agent .
    ?agent in:agentId ?agentId .
  }
}
GROUP BY ?agentId
ORDER BY ?agentId

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?claimNumber ?openDate ?closeDate
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:claimNumber ?claimNumber ;
           in:claimOpenDate ?openDate .
    OPTIONAL { ?claim in:claimCloseDate ?closeDate . }
  }
}
ORDER BY ?claimNumber

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?claimNumber
       (COALESCE(SUM(?lossPaymentAmt), 0) +
        COALESCE(SUM(?lossReserveAmt), 0) +
        COALESCE(SUM(?expensePaymentAmt), 0) +
        COALESCE(SUM(?expenseReserveAmt), 0) AS ?totalLoss)
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:claimNumber ?claimNumber .

    OPTIONAL {
      ?claim in:hasLossPayment ?lossPayment .
      ?lossPayment in:lossPaymentAmount ?lossPaymentAmt .
    }

    OPTIONAL {
      ?claim in:hasLossReserve ?lossReserve .
      ?lossReserve in:lossReserveAmount ?lossReserveAmt .
    }

    OPTIONAL {
      ?claim in:hasExpensePayment ?expensePayment .
      ?expensePayment in:expensePaymentAmount ?expensePaymentAmt .
    }

    OPTIONAL {
      ?claim in:hasExpenseReserve ?expenseReserve .
      ?expenseReserve in:expenseReserveAmount ?expenseReserveAmt .
    }
  }
}
GROUP BY ?claimNumber
ORDER BY ?claimNumber
